import { type Module } from '@divi/types';
/**
 * Get Background Options classnames.
 *
 * It returns classnames according to background options.
 * Note: right now background classnames only render parallax classnames. If at one point there's additional
 * background classnames, second parameters might be needed to decide settings. See `textOptionsClassnames()`.
 *
 * @since ??
 *
 * @param {Module.Element.Decoration.Background.Attributes} attr Background Group Attributes.
 *
 * @returns {string} Background classname.
 *
 * @example
 * ```tsx
 * const attrs = {
 *  background: {
 *  }
 * };
 * backgroundClassnames(attrs?.background)
 * // Returns '' If background is empty.
 * ```
 *
 * @example
 * ```tsx
 * const attrs = {
 *  background: {
 *    desktop: {
 *      value: {
 *        gradient: {
 *          enabled: 'off',
 *        },
 *        image: {
 *          parallax: {
 *            enabled: 'off',
 *          },
 *         url: '/images/1280x720/maxresdefault.jpg',
 *        },
 *        video: {
 *          allowPlayerPause:     'off',
 *          height:               'Lorem Ipsum',
 *          mp4:                  'https://www.youtube.com/watch?v=FkQuawiGWUw',
 *          pauseOutsideViewport: 'off',
 *          width:                'Lorem Ipsum',
 *        },
 *       },
 *     },
 *    },
 *  };
 * backgroundClassnames(attrs?.background)
 * // Returns 'et-pb-has-background-video'
 * ```
 *
 * @example
 * ```tsx
 * const attrs = {
 *  background: {
 *    desktop: {
 *       value: {
 *         image: {
 *           parallax: {
 *             enabled: "on"
 *           },
 *           url: "https://via.placeholder.com/500"
 *         }
 *       }
 *     }
 *  }
 * };
 * backgroundClassnames(attrs?.background)
 * // Returns 'et_pb_section_parallax'
 * ```
 */
export declare const backgroundClassnames: (attr: Module.Element.Decoration.Background.Attributes) => string;
